class TrafficLight {
    mutex m;
    int green = 1;

public:
    TrafficLight() {}

    void carArrived(int carId, int roadId, int direction,
                    function<void()> turnGreen,
                    function<void()> crossCar) {
        lock_guard<mutex> guard(m);
        if (green != roadId) {
            turnGreen();
            green = roadId;
        }
        crossCar();
    }
};
